// 28 - Verificar decisión y versión
// La IA nunca autoriza el envío: solo cuenta la decisión registrada por Slack.
// Antes de enviar se relee todo desde Airtable y se verifica que nada haya cambiado.
const aprob = $('26 - Slack: Solicitar aprobación').first().json;
const an = $('27a - Releer análisis').first().json;
const ld = $('27b - Releer lead').first().json;
const solicitado = $('17 - Validar borrador y generar huella').last().json;
const fa = an.fields ?? an;
const fl = ld.fields ?? ld;
const d = aprob.data ?? {};

// Decisión humana (sin respuesta dentro del plazo = expirado)
let decision = 'expirado';
if (d.approved === true) decision = 'aprobado';
else if (d.approved === false) decision = 'rechazado';

// Huella del borrador tal como está HOY en Airtable (misma función que el nodo 17)
const asunto = (fa.Borrador_Asunto ?? '').toString().trim();
const cuerpo = (fa.Borrador_Cuerpo ?? '').toString().trim();
const base = asunto + '\n' + cuerpo;
let h = 0x811c9dc5;
for (let i = 0; i < base.length; i++) { h ^= base.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
const hashActual = 'HB-' + h.toString(16).padStart(8, '0') + '-' + base.length;

const problemas = [];
if (decision === 'aprobado') {
  if (hashActual !== solicitado.hash_borrador) problemas.push(`El borrador cambió después de pedir la aprobación (${solicitado.hash_borrador} → ${hashActual})`);
  if ((fa.Hash_Borrador ?? '') !== solicitado.hash_borrador) problemas.push('Hash_Borrador guardado no coincide con la versión enviada a aprobar');
  if (fl.Estado !== 'Esperando aprobacion') problemas.push(`El lead está en "${fl.Estado}", no en "Esperando aprobacion"`);
  if (fl.Message_ID) problemas.push('Ya existe un envío registrado para este lead (Message_ID)');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test((fl.Email ?? '').toString())) problemas.push('Email del destinatario inválido');
}

const r = d.responder ?? {};
return [{ json: {
  ruta: decision === 'aprobado' ? (problemas.length ? 'bloqueado' : 'enviar') : decision,
  decision,
  problemas_texto: problemas.join('; '),
  hash_aprobado: decision === 'aprobado' ? hashActual : '',
  aprobador: r.id ? `${r.name || r.username || 'usuario'} (${r.id})` : (decision === 'expirado' ? 'sin respuesta' : ''),
  fecha_decision: d.respondedAt || new Date().toISOString(),
  slack_ts: d.messageId || '',
  lead_id: ld.id,
  lead_codigo: fl.Lead_ID || '',
  analisis_id: an.id,
  email: (fl.Email ?? '').toString(),
  asunto,
  cuerpo
}}];

// 37 - Preparar cierre
// Arma el registro final y el aviso de Slack según la rama que se ejecutó.
const v = $('28 - Verificar decisión y versión').first().json;
const corrio = n => { try { return $(n).isExecuted; } catch (e) { return false; } };
const quien = v.aprobador || 'sin respuesta';
let resultado = 'ok', etapa = '', detalle = '', texto = '';

if (v.ruta === 'enviar' && corrio('33 - Lead: Enviado')) {
  const g = $('32 - Gmail: Enviar respuesta aprobada').first().json;
  etapa = 'Aprobado por humano → email enviado';
  detalle = `Gmail id ${g.id} | thread ${g.threadId} | aprobado por ${quien} | versión ${v.hash_aprobado}`;
  texto = `✅ *Aprobado* por ${quien}. Email enviado a ${v.email}.`;
} else if (v.ruta === 'enviar') {
  let msg = 'Error desconocido';
  try { const e = $('32 - Gmail: Enviar respuesta aprobada').first().json; msg = e.error ? (e.error.message || JSON.stringify(e.error)) : JSON.stringify(e).slice(0, 500); } catch (e) {}
  resultado = 'error'; etapa = 'Envío por Gmail (falló tras reintentos)'; detalle = msg;
  texto = `⚠️ Aprobado por ${quien}, pero *falló el envío* del email. El lead quedó en Error.`;
} else if (v.ruta === 'rechazado') {
  etapa = 'Rechazado por humano'; detalle = `Rechazado por ${quien}. No se envió nada al cliente.`;
  texto = `❌ *Rechazado* por ${quien}. No se envió nada al cliente.`;
} else if (v.ruta === 'expirado') {
  etapa = 'Aprobación expirada'; detalle = 'Nadie respondió dentro del plazo. No se envió nada al cliente.';
  texto = `⏱️ La solicitud de aprobación *expiró* sin respuesta. No se envió nada al cliente.`;
} else {
  resultado = 'bloqueado'; etapa = 'Verificación previa al envío'; detalle = v.problemas_texto;
  texto = `⛔ Aprobación recibida, pero el *envío se bloqueó*: ${v.problemas_texto}`;
}

return [{ json: {
  lead_id: v.lead_id, etapa, resultado, detalle,
  slack_texto: `${v.lead_codigo ? v.lead_codigo + ' · ' : ''}${texto}`,
  slack_ts: v.slack_ts
}}];
